// TANK — five wheels, one barrel, zero negotiation.
// Drawn fighter: a plain ES module, no imports, everything from `api`.
//
//   STRIKE   (attack button)        the barrel clubs. Forward, up or down; charged is a full turret spin.
//   GIMMICK  (special button)       FIRE: a heavy shell, and the recoil shoves the tank back. Hold to charge.
//   RECOVERY (up + special)         fire straight down, the blast lifts the tank; steer with the stick.
//   GRAB     (grab button)          run them over with the tracks; the throw spits them out the way you hold.
//
// Fighter space: +x facing, +y DOWN, origin at the feet. Frames are 1-based.
export default function make(api) {
  const { hb, cap, key, mv, throwMove, spawnProjectile, spriteAnims, spriteLoops, B } = api;

  const stats = {
    weight: 135, walk: 2.3, run: 4.2, dashInit: 5, airSpeed: 3, airAccel: 0.12,
    fallSpeed: 9, fastFall: 13, gravity: 0.62, shortHop: 6, fullHop: 9, doubleJump: 7,
    jumps: 2, wallJump: false, traction: 0.3, height: 87, width: 124, crouchHeight: 62, landLag: 6, ledgeReach: 40,
  };

  const P = (extra) => ({ a: {}, ...extra });
  const rest = P({});
  const strikePoses = (total, hit, lean, extra = {}) => [
    key(0, P({ rot: -lean * 0.5, sx: 0.97, sy: 1.03, ...extra })),
    key(hit, P({ rot: lean, sx: 1.08, sy: 0.95, ...extra })),
    key(Math.min(total - 1, hit + 6), P({ rot: lean * 0.7, sx: 1.03, sy: 0.98, ...extra })),
    key(total, rest),
  ];
  const BARREL = { fx: "heavy" };

  // THE STRIKE: the barrel as a battering ram, from the turret to the muzzle as drawn in each cell.
  const STRIKE = { total: 34, hit: 11, active: 4, damage: 12, r: 13 };
  const aim = (id, dir, opts = {}) => {
    const s = { ...STRIKE, ...opts };
    const start = dir === "u" ? [5, -66] : dir === "d" ? [24, -58] : dir === "b" ? [-14, -63] : [14, -63];
    const end = dir === "u" ? [5, -122] : dir === "d" ? [58, -12] : dir === "b" ? [-72, -67] : [72, -67];
    const angle = dir === "u" ? 88 : dir === "d" ? 40 : 38;
    const lean = dir === "u" ? -4 : dir === "b" ? -12 : dir === "d" ? 10 : 8;
    const extra = dir === "u" ? { sy: 0.96 } : {};
    const cell = dir === "u" ? "atk-up" : dir === "d" ? "atk-down" : "atk-fwd";
    return mv(id, s.total, [cap([s.hit, s.hit + s.active - 1], start[0], start[1], end[0], end[1], s.r, s.damage, angle, s.base ?? 42, s.growth ?? 82, { ...BARREL, ...(s.hb ?? {}) })],
      strikePoses(s.total, s.hit, lean, extra), { cell, cellFlip: dir === "b", ...(s.mv ?? {}) });
  };
  // GRAB: the front of the track pins them; the toss goes the way you hold
  const GRAB = { total: 40, hit: 9, damage: 10 };
  const toss = (id, angle, base, growth, pose) => throwMove(id, 34, 15, GRAB.damage, angle, base, growth, [key(0, P({ rot: 4 })), key(15, P(pose)), key(34, rest)]);

  // a shell out of the drawn muzzle; the recoil shoves the whole tank backward
  const COOL = 45;
  const shoot = (state, f, charge, recoil) => {
    const q = charge / 60;
    spawnProjectile(state, f, "shell", f.x + f.moveFacing * 74, f.y - 67, f.moveFacing * (6 + q * 2), 0, 90,
      { frames: [0, 999], x: 0, y: 0, r: 10 + Math.floor(q * 8), damage: 8 + Math.floor(q * 10), angle: 35, base: 40 + Math.floor(q * 25), growth: 60 + Math.floor(q * 35), fx: "heavy" }, { g: 0 });
    f.vx = -f.moveFacing * (recoil + q * 6);
    f.special.cool = COOL;
  };

  const moves = {
    jab1: aim("jab1", "f", { total: 26, hit: 8, damage: 8, mv: { iasa: 20 } }),
    ftilt: aim("ftilt", "f"),
    dashAttack: aim("dashAttack", "f", { total: 40, hit: 11, damage: 12, mv: { motion: [[1, 6, 0], [12, 3, 0], [22, 0, 0]] } }),
    nair: aim("nair", "f", { total: 32, hit: 9, damage: 10, mv: { aerial: true, landingLag: 12 } }),
    fair: aim("fair", "f", { mv: { aerial: true, landingLag: 14 } }),
    bair: aim("bair", "b", { damage: 13, mv: { aerial: true, landingLag: 14 } }),
    utilt: aim("utilt", "u", { damage: 11 }),
    uair: aim("uair", "u", { damage: 11, mv: { aerial: true, landingLag: 12 } }),
    dtilt: aim("dtilt", "d", { damage: 10 }),
    dair: aim("dair", "d", { total: 42, hit: 14, damage: 13, hb: { spike: true }, mv: { aerial: true, landingLag: 18 } }),
    // the charged strike: a full turret spin, muzzle sweetspot in front then the barrel swings round behind
    fsmash: mv("fsmash", 56, [
      cap([17, 20], 50, -66, 74, -67, 15, 20, 36, 46, 100, { fx: "tip", priority: 0 }),
      cap([17, 20], 14, -63, 50, -66, 13, 15, 38, 40, 84, { ...BARREL, priority: 1 }),
      cap([25, 28], -14, -63, -72, -67, 14, 12, 40, 40, 80, { ...BARREL, group: 1 }),
    ], [key(0, P({ rot: -6, sx: 0.95 })), key(17, P({ rot: 10, sx: 1.12, sy: 0.93 })), key(25, P({ rot: -8, sx: 1.08 })), key(56, rest)], { smash: true, cell: "atk-fwd" }),
    usmash: aim("usmash", "u", { total: 52, hit: 16, active: 6, damage: 18, base: 44, growth: 100, mv: { smash: true } }),
    dsmash: mv("dsmash", 56, [
      cap([17, 20], 24, -58, 58, -12, 15, 17, 30, 45, 90, { ...BARREL, group: 0 }),
      cap([24, 27], -24, -58, -58, -12, 15, 15, 30, 45, 86, { ...BARREL, group: 1 }),
    ], [key(0, P({ sy: 0.92 })), key(17, P({ rot: 12, sx: 1.1, sy: 0.9 })), key(24, P({ rot: -12, sx: 1.1, sy: 0.9 })), key(56, rest)], { smash: true, cell: "atk-down" }),
    // grab: roll onto them with the front of the track
    grab: mv("grab", GRAB.total, [hb([GRAB.hit, GRAB.hit + 2], 58, -18, 24, 0, 0, 0, 0, { grab: true })], strikePoses(GRAB.total, GRAB.hit, 6), { isGrab: true, motion: [[1, 2, 0], [GRAB.hit, 0, 0]] }),
    dashGrab: mv("dashGrab", 46, [hb([11, 13], 66, -18, 26, 0, 0, 0, 0, { grab: true })], strikePoses(46, 11, 10), { isGrab: true, motion: [[1, 5, 0], [11, 0, 0]] }),
    pummel: mv("pummel", 18, [], [key(0, P({ rot: 3 })), key(6, P({ sy: 0.9, sx: 1.06 })), key(18, P({ rot: 3 }))]),
    fthrow: toss("fthrow", 40, 62, 74, { rot: -8, sx: 1.1 }),
    bthrow: toss("bthrow", 35, 66, 80, { rot: -14, dx: -10 }),
    uthrow: toss("uthrow", 90, 70, 88, { dy: -10, sy: 1.12 }),
    dthrow: toss("dthrow", 70, 45, 42, { sy: 0.82, sx: 1.12, dy: 8 }),
    // GIMMICK, FIRE: hold to charge a bigger shell and a bigger kick
    nspecial: mv("nspecial", 50, [], [key(0, P({ sy: 0.96 })), key(15, P({ rot: -3, sx: 0.94 })), key(16, P({ rot: -10, sx: 1.1, sy: 0.92 })), key(30, P({ rot: -3 })), key(50, rest)], { hook: "fire", cell: "atk-fwd" }),
    // sideways: a snap shot, no charge, a harder shove
    sspecial: mv("sspecial", 40, [], [key(0, rest), key(10, P({ rot: -12, sx: 1.1, sy: 0.92 })), key(40, rest)], { hook: "snap", cell: "atk-fwd" }),
    // down: fire into the floor and bounce off the blast (once per airtime)
    dspecial: mv("dspecial", 44, [hb([12, 15], 56, -8, 30, 10, 70, 45, 62, { fx: "heavy" })], [key(0, P({ sy: 0.94 })), key(12, P({ rot: 8, sy: 1.1 })), key(44, rest)], { hook: "bounce", cell: "atk-down", fx: "quake" }),
    // RECOVERY: barrel straight down, the blast carries the tank up; the stick steers it
    uspecial: mv("uspecial", 60, [hb([6, 10], 0, 8, 38, 9, 80, 45, 60, { fx: "heavy" })], [key(0, P({ sy: 0.86, sx: 1.1 })), key(6, P({ sy: 1.14, sx: 0.92 })), key(34, P({ rot: 6 })), key(60, P({ rot: -6 }))], { hook: "lift", helpless: true, ledgeOk: true, cell: "jump", fx: "quake" }),
    ledgeAttack: aim("ledgeAttack", "f", { total: 40, hit: 13, damage: 9 }),
    getupAttack: mv("getupAttack", 44, [cap([12, 15], 14, -63, 72, -67, 13, 7, 45, 40, 60, { ...BARREL, group: 0 }), cap([20, 23], -14, -63, -72, -67, 13, 7, 45, 40, 60, { ...BARREL, group: 1 })], [key(0, rest), key(12, P({ rot: 8 })), key(20, P({ rot: -8 })), key(44, rest)]),
    taunt: mv("taunt", 50, [], [key(0, rest), key(12, P({ rot: -6, sy: 1.08 })), key(20, P({ rot: -12, sx: 1.1 })), key(50, rest)], { cell: "atk-up" }),
  };

  return {
    id: "tank",
    name: "TANK",
    tagline: "Five wheels, one barrel, zero negotiation.",
    stats,
    moves,
    rig: { bones: [], anims: spriteAnims(), loops: spriteLoops },
    palette: { colors: { hull: "#2e9a58", wheels: "#ee8a2c" }, accent: "hull", outline: "#262626" },
    special: () => ({ charge: 0, cool: 0, bounced: 0 }),
    hooks: {
      fire: ({ state, f, input }) => {
        if (f.frame <= 15 && f.special.charge < 60 && (input.b & B.SPECIAL)) {
          f.special.charge++;
          if (f.frame === 15) f.frame = 14;
          return;
        }
        if (f.frame === 16) {
          if (f.special.cool === 0) shoot(state, f, f.special.charge, 8);
          else f.vx = -f.moveFacing * 3;
          f.special.charge = 0;
        }
      },
      snap: ({ state, f }) => {
        if (f.frame === 10) {
          if (f.special.cool === 0) shoot(state, f, 0, 11);
          else f.vx = -f.moveFacing * 3;
        }
      },
      bounce: ({ f }) => {
        if (f.frame === 12 && f.special.bounced === 0) {
          f.grounded = false; f.platform = -1; f.special.bounced = 1;
          f.vy = -10; f.vx = -f.moveFacing * 3;
        }
      },
      lift: ({ f, input }) => {
        if (f.frame === 6) { f.grounded = false; f.platform = -1; f.usedUpSpecial = true; }
        if (f.frame >= 6 && f.frame <= 40) {
          f.vy = -10 + (f.frame - 6) * 0.2;
          f.vx = (input.x / 100) * 6;
        }
      },
    },
    onFrame: ({ f }) => {
      if (f.special.cool > 0) f.special.cool--;
      if (f.grounded) f.special.bounced = 0;
    },
    meters: [{ label: "SHELL", color: "#ee8a2c", get: (f) => 1 - f.special.cool / COOL }],
    visual: (f) => ({ glow: f.special.charge / 60 }),
  };
}
